{"title": "CERT OPS — Key Algorithm", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? null : datum.k", "force": true}]
    },
    {
      "name": "_kf", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? kibanaRemoveFilter({'match_phrase': {'certificate.subject_public_key_info.algorithm': datum.k}}) : kibanaAddFilter({'match_phrase': {'certificate.subject_public_key_info.algorithm': datum.k}})", "force": true}]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {
          "by_algo": {"terms": {"field": "certificate.subject_public_key_info.algorithm", "size": 10}},
          "total":   {"value_count": {"field": "id"}}
        }}},
      "format": {"property": "aggregations.by_algo.buckets"},
      "transform": [
        {"type": "formula", "as": "k",   "expr": "datum.key"},
        {"type": "formula", "as": "n",   "expr": "datum.doc_count"}
      ]
    },
    {
      "name": "tot",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {"v": {"value_count": {"field": "id"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {
      "name": "palette",
      "values": [
        {"k": "RSA",         "clr": "#ffa726", "bg": "#ffa72618", "lbl": "RSA",         "desc": "Rivest–Shamir–Adleman — quantum-vulnerable via Shor's algorithm"},
        {"k": "ECDSA",       "clr": "#448aff", "bg": "#448aff18", "lbl": "ECDSA",       "desc": "Elliptic curve — quantum-vulnerable, efficient on classical hardware"},
        {"k": "DSA",         "clr": "#ef5350", "bg": "#ef535018", "lbl": "DSA",         "desc": "Digital Signature Algorithm — deprecated, should not be in new certs"},
        {"k": "unknown_der", "clr": "#78909c", "bg": "#78909c18", "lbl": "Unknown DER", "desc": "DER-encoded cert with unrecognized key OID"},
        {"k": "unknown_pem", "clr": "#78909c", "bg": "#78909c18", "lbl": "Unknown PEM", "desc": "PEM-encoded cert with unrecognized key OID"},
        {"k": "ML-DSA",      "clr": "#00c853", "bg": "#00c85318", "lbl": "ML-DSA",      "desc": "Lattice-based PQC signature — CNSA 2.0 quantum-resistant"},
        {"k": "SLH-DSA",     "clr": "#00c853", "bg": "#00c85318", "lbl": "SLH-DSA",     "desc": "Hash-based PQC signature — CNSA 2.0 quantum-resistant"},
        {"k": "FN-DSA",      "clr": "#00c853", "bg": "#00c85318", "lbl": "FN-DSA",      "desc": "Falcon lattice signature — CNSA 2.0 quantum-resistant"}
      ]
    },
    {
      "name": "rows",
      "source": "raw",
      "transform": [
        {"type": "lookup", "from": "palette", "key": "k", "fields": ["k"],
         "values": ["clr", "bg", "lbl", "desc"], "as": ["clr", "bg", "lbl", "desc"],
         "default": "#78909c"},
        {"type": "formula", "as": "clr",  "expr": "datum.clr  || '#78909c'"},
        {"type": "formula", "as": "bg",   "expr": "datum.bg   || '#78909c18'"},
        {"type": "formula", "as": "lbl",  "expr": "datum.lbl  || datum.k"},
        {"type": "formula", "as": "desc", "expr": "datum.desc || 'Unrecognized key algorithm'"},
        {"type": "collect", "sort": {"field": "n", "order": "descending"}},
        {"type": "window", "ops": ["rank"], "as": ["rnk"]},
        {"type": "formula", "as": "y",   "expr": "(datum.rnk - 1) * 70 + 52"},
        {"type": "formula", "as": "tot", "expr": "length(data('tot'))>0 ? data('tot')[0].n : 1"},
        {"type": "formula", "as": "pct", "expr": "datum.tot > 0 ? datum.n / datum.tot : 0"},
        {"type": "formula", "as": "bw",  "expr": "width * 0.58 - 110"}
      ]
    },
    {
      "name": "mx",
      "source": "rows",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 18},
        "text": {"value": "KEY ALGORITHM"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 34},
        "text": {"value": "PUBLIC KEY TYPE  —  click to filter"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 42},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect", "name": "bg",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 64},
        "fill": {"signal": "datum.k===sel ? '#1c1c2e' : datum.n>0 ? '#161622' : '#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 4}, "height": {"value": 64},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 63"},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 22"},
        "text": {"field": "lbl"}, "limit": {"signal": "width * 0.4"},
        "fill": {"value": "#e8e8e8"}, "fontSize": {"value": 13}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 40"},
        "text": {"field": "desc"}, "limit": {"signal": "width * 0.56"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.58"}, "y": {"signal": "datum.y + 22"},
        "width": {"signal": "length(data('mx'))>0 && data('mx')[0].v > 0 ? (datum.n / data('mx')[0].v) * (width * 0.30) : 0"},
        "height": {"value": 10}, "cornerRadius": {"value": 2},
        "fill": {"signal": "datum.k===sel ? datum.clr : datum.clr + '88'"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 36"},
        "text": {"signal": "datum.n >= 1000 ? format(datum.n,'.3~s') : format(datum.n,',')"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#dddddd'"},
        "fontSize": {"value": 18}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 50"},
        "text": {"signal": "format(datum.pct * 100, '.1f') + '%'"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}
"}}
